   opening="<div class='opening' role='dialog' aria-modal='true' aria-label='Welcome to Muhammad Subhan’s portfolio'><div class='opening-top'><span><b>MS</b>A developing perspective</span><button data-skip-intro>Skip intro</button></div><div class='opening-content'><p class='eyebrow'>The story so far</p><h2 class='opening-name'><span><i>Muhammad</i></span><span><i>Subhan.</i></span></h2><p class='opening-caption'>A future in law.<br>Built one step at a time.</p></div><div class='opening-bottom'><span>Riyadh, Saudi Arabia</span><div class='opening-track' aria-hidden='true'></div><span>Personal portfolio / 2026</span></div></div>"
